package inventorymanagement;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.table.*;
import java.awt.*;
import java.math.BigDecimal;
import java.sql.*;
import java.util.Vector;

/** Main application window. The small helper methods keep SQL close to each UI action. */
public class Dashboard extends JFrame {
    private final String username;
    private final JTabbedPane tabs = new JTabbedPane();
    private final JPanel home = new JPanel(new BorderLayout(14,14));
    private final JTable productsTable = new JTable(), suppliersTable = new JTable(), ordersTable = new JTable();
    private final JTextField search = new JTextField(20);
    private final Color blue = new Color(34,91,163);
    public Dashboard(String username) {
        super("Inventory & Stock Management"); this.username=username; setDefaultCloseOperation(EXIT_ON_CLOSE); setMinimumSize(new Dimension(1050,680)); setSize(1180,760); setLocationRelativeTo(null);
        JPanel root = new JPanel(new BorderLayout()); root.add(sidebar(),BorderLayout.WEST); JPanel content = new JPanel(new BorderLayout()); content.add(header(),BorderLayout.NORTH);
        tabs.addTab("Overview",home); tabs.addTab("Products",productPanel()); tabs.addTab("Suppliers",supplierPanel()); tabs.addTab("Purchase Orders",orderPanel());
        content.add(tabs,BorderLayout.CENTER); root.add(content,BorderLayout.CENTER); setContentPane(root); refreshAll();
    }
    private JPanel sidebar() {
        JPanel p=new JPanel(); p.setPreferredSize(new Dimension(190,0)); p.setBackground(new Color(25,55,96)); p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS)); p.setBorder(new EmptyBorder(24,14,16,14));
        JLabel brand=new JLabel("STOCKFLOW"); brand.setForeground(Color.WHITE); brand.setFont(new Font("SansSerif",Font.BOLD,19)); brand.setBorder(new EmptyBorder(0,4,28,0)); p.add(brand);
        String[] names={"Overview","Products","Suppliers","Purchase Orders"}; for(int i=0;i<names.length;i++){ final int index=i; JButton b=new JButton(names[i]); b.setHorizontalAlignment(SwingConstants.LEFT); b.setMaximumSize(new Dimension(170,42)); b.setForeground(Color.WHITE); b.setBackground(new Color(25,55,96)); b.setBorderPainted(false); b.setFocusPainted(false); b.addActionListener(e->tabs.setSelectedIndex(index)); p.add(b); p.add(Box.createVerticalStrut(6)); }
        p.add(Box.createVerticalGlue()); JLabel signed=new JLabel("Signed in: "+username); signed.setForeground(new Color(210,220,235)); p.add(signed); return p;
    }
    private JPanel header(){ JPanel p=new JPanel(new BorderLayout()); p.setBorder(new EmptyBorder(16,22,14,22)); p.setBackground(Color.WHITE); JLabel title=new JLabel("Inventory & Stock Management"); title.setFont(new Font("SansSerif",Font.BOLD,20)); title.setForeground(new Color(35,55,80)); p.add(title,BorderLayout.WEST); JButton refresh=new JButton("Refresh data"); refresh.addActionListener(e->refreshAll()); p.add(refresh,BorderLayout.EAST); return p; }
    private JPanel productPanel(){ JPanel p=new JPanel(new BorderLayout(8,8)); p.setBorder(new EmptyBorder(12,16,16,16)); JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT)); tools.add(new JLabel("Search")); tools.add(search); JButton find=new JButton("Search"),add=new JButton("Add product"),edit=new JButton("Update"),del=new JButton("Delete"),in=new JButton("Stock in"),out=new JButton("Stock out"); tools.add(find); tools.add(add); tools.add(edit); tools.add(del); tools.add(in); tools.add(out); p.add(tools,BorderLayout.NORTH); styleTable(productsTable); p.add(new JScrollPane(productsTable),BorderLayout.CENTER);
        find.addActionListener(e->loadProducts(search.getText().trim())); search.addActionListener(e->loadProducts(search.getText().trim())); add.addActionListener(e->productDialog(null)); edit.addActionListener(e->{Integer id=selectedId(productsTable);if(id!=null)productDialog(id);}); del.addActionListener(e->deleteProduct()); in.addActionListener(e->moveStock(true)); out.addActionListener(e->moveStock(false)); return p; }
    private JPanel supplierPanel(){ JPanel p=new JPanel(new BorderLayout(8,8)); p.setBorder(new EmptyBorder(12,16,16,16)); JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT)); JButton add=new JButton("Add supplier"),edit=new JButton("Update"),del=new JButton("Delete"); tools.add(add);tools.add(edit);tools.add(del);p.add(tools,BorderLayout.NORTH);styleTable(suppliersTable);p.add(new JScrollPane(suppliersTable),BorderLayout.CENTER);add.addActionListener(e->supplierDialog(null));edit.addActionListener(e->supplierDialog(selectedId(suppliersTable)));del.addActionListener(e->deleteSupplier());return p; }
    private JPanel orderPanel(){ JPanel p=new JPanel(new BorderLayout(8,8));p.setBorder(new EmptyBorder(12,16,16,16));JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton generate=new JButton("Generate low-stock drafts"),approve=new JButton("Approve"),reject=new JButton("Reject"),receive=new JButton("Receive goods");tools.add(generate);tools.add(approve);tools.add(reject);tools.add(receive);p.add(tools,BorderLayout.NORTH);styleTable(ordersTable);p.add(new JScrollPane(ordersTable),BorderLayout.CENTER);generate.addActionListener(e->generateOrders());approve.addActionListener(e->setOrderStatus("APPROVED"));reject.addActionListener(e->setOrderStatus("REJECTED"));receive.addActionListener(e->receiveOrder());return p; }
    private void styleTable(JTable t){t.setRowHeight(27);t.setAutoCreateRowSorter(true);t.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);t.setDefaultRenderer(Object.class,new StockRenderer());}
    private void refreshAll(){ refreshHome();loadProducts("");loadSuppliers();loadOrders(); }
    private void refreshHome(){
        home.removeAll(); home.setBorder(new EmptyBorder(20,22,22,22)); JPanel cards=new JPanel(new GridLayout(1,4,14,0)); cards.setOpaque(false);
        String[][] stats={{"Products","SELECT COUNT(*) FROM products"},{"Units in stock","SELECT COALESCE(SUM(quantity),0) FROM products"},{"Low-stock items","SELECT COUNT(*) FROM products WHERE quantity<=min_stock"},{"Pending orders","SELECT COUNT(*) FROM purchase_orders WHERE status IN ('DRAFT','APPROVED')"}};
        try(Connection c=DBConnection.getConnection();Statement s=c.createStatement()){for(String[] stat:stats){String val="0";try(ResultSet rs=s.executeQuery(stat[1])){if(rs.next())val=rs.getString(1);}cards.add(card(stat[0],val));}}catch(SQLException ex){error(ex);}
        home.add(cards,BorderLayout.NORTH); JPanel lower=new JPanel(new GridLayout(1,2,14,0));lower.setOpaque(false);JPanel quick=boxed("Quick actions");JButton add=new JButton("Add product"),stock=new JButton("Record stock movement"),orders=new JButton("Create low-stock drafts");quick.add(add);quick.add(stock);quick.add(orders);add.addActionListener(e->{tabs.setSelectedIndex(1);productDialog(null);});stock.addActionListener(e->{tabs.setSelectedIndex(1);moveStock(true);});orders.addActionListener(e->{tabs.setSelectedIndex(3);generateOrders();});JPanel alert=boxed("Low-stock alerts");JTable low=new JTable();styleTable(low);alert.add(new JScrollPane(low));try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT product_id,product_name,quantity,min_stock FROM products WHERE quantity<=min_stock ORDER BY quantity");ResultSet rs=p.executeQuery()){low.setModel(model(rs));}catch(SQLException ex){error(ex);}lower.add(quick);lower.add(alert);home.add(lower,BorderLayout.CENTER);home.revalidate();home.repaint();
    }
    private JPanel card(String title,String value){JPanel p=new JPanel(new BorderLayout(5,12));p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(225,231,239)),new EmptyBorder(17,18,17,18)));JLabel t=new JLabel(title);t.setForeground(new Color(100,112,128));JLabel v=new JLabel(value);v.setFont(new Font("SansSerif",Font.BOLD,28));v.setForeground(blue);p.add(t,BorderLayout.NORTH);p.add(v,BorderLayout.CENTER);return p;}
    private JPanel boxed(String title){JPanel p=new JPanel();p.setBackground(Color.WHITE);p.setBorder(BorderFactory.createTitledBorder(title));p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));return p;}
    private void loadProducts(String term){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT p.product_id,p.product_name,p.category,COALESCE(s.supplier_name,'—') supplier,p.quantity,p.min_stock,p.price FROM products p LEFT JOIN suppliers s ON s.supplier_id=p.supplier_id WHERE p.product_name LIKE ? OR p.category LIKE ? ORDER BY p.product_id")){p.setString(1,"%"+term+"%");p.setString(2,"%"+term+"%");try(ResultSet rs=p.executeQuery()){productsTable.setModel(model(rs));}}catch(SQLException ex){error(ex);}}
    private void loadSuppliers(){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT supplier_id,supplier_name,phone,email,address FROM suppliers ORDER BY supplier_name");ResultSet rs=p.executeQuery()){suppliersTable.setModel(model(rs));}catch(SQLException ex){error(ex);}}
    private void loadOrders(){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT po.po_id,p.product_name,s.supplier_name,po.order_quantity,po.total_amount,po.status,po.created_at FROM purchase_orders po JOIN products p ON p.product_id=po.product_id LEFT JOIN suppliers s ON s.supplier_id=po.supplier_id ORDER BY po.created_at DESC");ResultSet rs=p.executeQuery()){ordersTable.setModel(model(rs));}catch(SQLException ex){error(ex);}}
    private DefaultTableModel model(ResultSet rs)throws SQLException{ResultSetMetaData md=rs.getMetaData();Vector<String> cols=new Vector<>();for(int i=1;i<=md.getColumnCount();i++)cols.add(md.getColumnLabel(i));Vector<Vector<Object>> rows=new Vector<>();while(rs.next()){Vector<Object> row=new Vector<>();for(int i=1;i<=md.getColumnCount();i++)row.add(rs.getObject(i));rows.add(row);}return new DefaultTableModel(rows,cols){public boolean isCellEditable(int r,int c){return false;}};}
    private Integer selectedId(JTable t){int row=t.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a row first.");return null;}return Integer.parseInt(t.getValueAt(t.convertRowIndexToModel(row),0).toString());}
    private void productDialog(Integer id){
        JTextField name=new JTextField(),category=new JTextField(),quantity=new JTextField("0"),minimum=new JTextField("0"),price=new JTextField("0.00");JComboBox<Item> supplierBox=supplierChoices();if(id!=null){try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT product_name,category,supplier_id,quantity,min_stock,price FROM products WHERE product_id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(r.next()){name.setText(r.getString(1));category.setText(r.getString(2));selectSupplier(supplierBox,r.getInt(3));quantity.setText(r.getString(4));minimum.setText(r.getString(5));price.setText(r.getString(6));}}}catch(SQLException ex){error(ex);return;}}
        JPanel form=new JPanel(new GridLayout(0,2,8,8));form.add(new JLabel("Product name"));form.add(name);form.add(new JLabel("Category"));form.add(category);form.add(new JLabel("Supplier"));form.add(supplierBox);form.add(new JLabel("Quantity"));form.add(quantity);form.add(new JLabel("Minimum stock"));form.add(minimum);form.add(new JLabel("Unit price"));form.add(price);
        if(JOptionPane.showConfirmDialog(this,form,id==null?"Add product":"Update product",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;
        try{String n=name.getText().trim(),cat=category.getText().trim();int q=Integer.parseInt(quantity.getText().trim()),m=Integer.parseInt(minimum.getText().trim());BigDecimal cost=new BigDecimal(price.getText().trim());if(n.isEmpty()||cat.isEmpty()||q<0||m<0||cost.signum()<0)throw new IllegalArgumentException();Item sup=(Item)supplierBox.getSelectedItem();try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{int previous=-1;if(id!=null)try(PreparedStatement old=c.prepareStatement("SELECT quantity FROM products WHERE product_id=? FOR UPDATE")){old.setInt(1,id);try(ResultSet r=old.executeQuery()){if(!r.next())throw new SQLException("Product no longer exists.");previous=r.getInt(1);}}try(PreparedStatement p=c.prepareStatement(id==null?"INSERT INTO products(product_name,category,supplier_id,quantity,min_stock,price) VALUES(?,?,?,?,?,?)":"UPDATE products SET product_name=?,category=?,supplier_id=?,quantity=?,min_stock=?,price=? WHERE product_id=?")){p.setString(1,n);p.setString(2,cat);if(sup==null)p.setNull(3,Types.INTEGER);else p.setInt(3,sup.id);p.setInt(4,q);p.setInt(5,m);p.setBigDecimal(6,cost);if(id!=null)p.setInt(7,id);p.executeUpdate();}int productId=id==null?0:id;if(id==null)try(Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT LAST_INSERT_ID()")){r.next();productId=r.getInt(1);}int delta=id==null?q:q-previous;if(delta!=0)try(PreparedStatement movement=c.prepareStatement("INSERT INTO stock_movements(product_id,movement_type,quantity,note) VALUES(?,?,?,'Product form quantity adjustment')")){movement.setInt(1,productId);movement.setString(2,delta>0?"IN":"OUT");movement.setInt(3,Math.abs(delta));movement.executeUpdate();}c.commit();}catch(Exception ex){c.rollback();throw ex;}}refreshAll();}catch(Exception ex){JOptionPane.showMessageDialog(this,"Enter a name and category, non-negative whole quantities, and a valid non-negative price. Details: "+ex.getMessage(),"Invalid product",JOptionPane.WARNING_MESSAGE);}}
    private JComboBox<Item> supplierChoices(){JComboBox<Item> box=new JComboBox<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT supplier_id,supplier_name FROM suppliers ORDER BY supplier_name");ResultSet r=p.executeQuery()){while(r.next())box.addItem(new Item(r.getInt(1),r.getString(2)));}catch(SQLException ex){error(ex);}return box;}
    private void selectSupplier(JComboBox<Item>b,int id){for(int i=0;i<b.getItemCount();i++)if(b.getItemAt(i).id==id)b.setSelectedIndex(i);}
    private record Item(int id,String name){public String toString(){return name;}}
    private void deleteProduct(){Integer id=selectedId(productsTable);if(id==null)return;if(JOptionPane.showConfirmDialog(this,"Delete this product? Existing purchase or movement history prevents deletion.","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM products WHERE product_id=?")){p.setInt(1,id);p.executeUpdate();refreshAll();}catch(SQLException ex){JOptionPane.showMessageDialog(this,"Product is referenced by order or stock history and cannot be deleted.","Delete failed",JOptionPane.WARNING_MESSAGE);}}
    private void moveStock(boolean stockIn){Integer id=selectedId(productsTable);if(id==null)return;String raw=JOptionPane.showInputDialog(this,"Quantity to "+(stockIn?"add":"remove")+":");if(raw==null)return;try{int amount=Integer.parseInt(raw);if(amount<=0)throw new NumberFormatException();String note=JOptionPane.showInputDialog(this,"Note (optional):");try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{int current;try(PreparedStatement q=c.prepareStatement("SELECT quantity FROM products WHERE product_id=? FOR UPDATE")){q.setInt(1,id);try(ResultSet r=q.executeQuery()){if(!r.next())throw new SQLException("Product not found");current=r.getInt(1);}}if(!stockIn&&amount>current)throw new SQLException("Stock-out exceeds available stock.");try(PreparedStatement u=c.prepareStatement("UPDATE products SET quantity=? WHERE product_id=?")){u.setInt(1,stockIn?current+amount:current-amount);u.setInt(2,id);u.executeUpdate();}try(PreparedStatement m=c.prepareStatement("INSERT INTO stock_movements(product_id,movement_type,quantity,note) VALUES(?,?,?,?)")){m.setInt(1,id);m.setString(2,stockIn?"IN":"OUT");m.setInt(3,amount);m.setString(4,note);m.executeUpdate();}c.commit();}catch(Exception ex){c.rollback();throw ex;}}refreshAll();}catch(NumberFormatException ex){JOptionPane.showMessageDialog(this,"Quantity must be a positive whole number.");}catch(Exception ex){error(ex);}}
    private void supplierDialog(Integer id){JTextField name=new JTextField(),phone=new JTextField(),email=new JTextField(),address=new JTextField();if(id!=null)try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT supplier_name,phone,email,address FROM suppliers WHERE supplier_id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(r.next()){name.setText(r.getString(1));phone.setText(r.getString(2));email.setText(r.getString(3));address.setText(r.getString(4));}}}catch(SQLException ex){error(ex);return;}JPanel f=new JPanel(new GridLayout(0,2,8,8));for(Object[] x:new Object[][]{{"Name",name},{"Phone",phone},{"Email",email},{"Address",address}}){f.add(new JLabel(x[0].toString()));f.add((Component)x[1]);}if(JOptionPane.showConfirmDialog(this,f,id==null?"Add supplier":"Update supplier",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;if(name.getText().isBlank()){JOptionPane.showMessageDialog(this,"Supplier name is required.");return;}try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement(id==null?"INSERT INTO suppliers(supplier_name,phone,email,address) VALUES(?,?,?,?)":"UPDATE suppliers SET supplier_name=?,phone=?,email=?,address=? WHERE supplier_id=?")){p.setString(1,name.getText().trim());p.setString(2,phone.getText().trim());p.setString(3,email.getText().trim());p.setString(4,address.getText().trim());if(id!=null)p.setInt(5,id);p.executeUpdate();refreshAll();}catch(SQLException ex){error(ex);}}
    private void deleteSupplier(){Integer id=selectedId(suppliersTable);if(id==null)return;if(JOptionPane.showConfirmDialog(this,"Delete this supplier? Suppliers referenced by products or purchase orders cannot be removed.","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try(Connection c=DBConnection.getConnection();PreparedStatement check=c.prepareStatement("SELECT (SELECT COUNT(*) FROM products WHERE supplier_id=?)+(SELECT COUNT(*) FROM purchase_orders WHERE supplier_id=?)")){check.setInt(1,id);check.setInt(2,id);try(ResultSet r=check.executeQuery()){r.next();if(r.getInt(1)>0){JOptionPane.showMessageDialog(this,"Supplier is referenced by existing records and cannot be deleted.","Delete failed",JOptionPane.WARNING_MESSAGE);return;}}try(PreparedStatement p=c.prepareStatement("DELETE FROM suppliers WHERE supplier_id=?")){p.setInt(1,id);p.executeUpdate();}refreshAll();}catch(SQLException ex){error(ex);}}
    private void generateOrders(){int made=0;try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try(PreparedStatement low=c.prepareStatement("SELECT product_id,supplier_id,quantity,min_stock,price FROM products WHERE quantity<=min_stock");ResultSet r=low.executeQuery()){while(r.next()){int pid=r.getInt(1),sid=r.getInt(2);boolean noSupplier=r.wasNull();int qty=r.getInt(3),min=r.getInt(4),suggested=Math.max(1,2*min-qty);try(PreparedStatement exists=c.prepareStatement("SELECT 1 FROM purchase_orders WHERE product_id=? AND status IN ('DRAFT','APPROVED')")){exists.setInt(1,pid);try(ResultSet x=exists.executeQuery()){if(x.next())continue;}}try(PreparedStatement ins=c.prepareStatement("INSERT INTO purchase_orders(product_id,supplier_id,order_quantity,total_amount,status) VALUES(?,?,?,?, 'DRAFT')")){ins.setInt(1,pid);if(noSupplier)ins.setNull(2,Types.INTEGER);else ins.setInt(2,sid);ins.setInt(3,suggested);ins.setBigDecimal(4,r.getBigDecimal(5).multiply(BigDecimal.valueOf(suggested)));ins.executeUpdate();made++;}}}c.commit();JOptionPane.showMessageDialog(this,"Created "+made+" purchase-order draft(s).");refreshAll();}catch(Exception ex){error(ex);}}
    private void setOrderStatus(String status){Integer id=selectedId(ordersTable);if(id==null)return;try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE purchase_orders SET status=? WHERE po_id=? AND status='DRAFT'")){p.setString(1,status);p.setInt(2,id);if(p.executeUpdate()==0)JOptionPane.showMessageDialog(this,"Only draft orders can be approved or rejected.");refreshAll();}catch(SQLException ex){error(ex);}}
    private void receiveOrder(){Integer id=selectedId(ordersTable);if(id==null)return;if(JOptionPane.showConfirmDialog(this,"Mark this approved order as received and add its quantity to stock?","Receive goods",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{int pid,qty;try(PreparedStatement p=c.prepareStatement("SELECT product_id,order_quantity FROM purchase_orders WHERE po_id=? AND status='APPROVED' FOR UPDATE")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){if(!r.next())throw new SQLException("Only approved orders can be received.");pid=r.getInt(1);qty=r.getInt(2);}}try(PreparedStatement p=c.prepareStatement("UPDATE products SET quantity=quantity+? WHERE product_id=?")){p.setInt(1,qty);p.setInt(2,pid);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("INSERT INTO stock_movements(product_id,movement_type,quantity,note) VALUES(?,'IN',?,'Purchase order received')")){p.setInt(1,pid);p.setInt(2,qty);p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE purchase_orders SET status='RECEIVED' WHERE po_id=?")){p.setInt(1,id);p.executeUpdate();}c.commit();}catch(Exception ex){c.rollback();throw ex;}}catch(Exception ex){error(ex);}refreshAll();}
    private void error(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Operation failed",JOptionPane.ERROR_MESSAGE);}
    private class StockRenderer extends DefaultTableCellRenderer {public Component getTableCellRendererComponent(JTable table,Object value,boolean selected,boolean focus,int row,int col){Component c=super.getTableCellRendererComponent(table,value,selected,focus,row,col);if(!selected){int qtyCol=-1,minCol=-1;for(int i=0;i<table.getModel().getColumnCount();i++){String label=table.getModel().getColumnName(i);if(label.equalsIgnoreCase("quantity"))qtyCol=i;if(label.equalsIgnoreCase("min_stock"))minCol=i;}if(qtyCol>=0&&minCol>=0){int modelRow=table.convertRowIndexToModel(row);try{int qty=Integer.parseInt(table.getModel().getValueAt(modelRow,qtyCol).toString()),min=Integer.parseInt(table.getModel().getValueAt(modelRow,minCol).toString());c.setBackground(qty==0?new Color(255,205,205):qty<=min?new Color(255,239,184):new Color(218,244,224));}catch(Exception ignored){c.setBackground(Color.WHITE);}}else c.setBackground(Color.WHITE);}return c;}}
}
